params.command:
$ErrorActionPreference='Stop'
$repo='C:\Users\Xxkan\mhw-mods-work-canonical'
$wt='C:\Users\Xxkan\HeavenWorktrees\hcp-indexing-5568db9'
if (Test-Path $wt) { throw "verification worktree already exists: $wt" }
git -C $repo fetch --quiet origin agent/hcp-indexing-20260929-0746
if ($LASTEXITCODE -ne 0) { throw 'git fetch failed' }
git -C $repo worktree add --detach $wt 5568db911a00726cf874d642a63753571471c807
if ($LASTEXITCODE -ne 0) { throw 'git worktree add failed' }
try {
  python "$wt\plugins\heaven-control-plane\verify.py"
  if ($LASTEXITCODE -ne 0) { throw 'control-plane verify failed' }
  git -C $wt diff --check
  if ($LASTEXITCODE -ne 0) { throw 'git diff --check failed' }
  $head=(git -C $wt rev-parse HEAD).Trim()
  $status=(git -C $wt status --short)
  [pscustomobject]@{head=$head;clean=([string]::IsNullOrWhiteSpace(($status -join '')))} | ConvertTo-Json -Compress
} finally {
  git -C $repo worktree remove --force $wt
}
